// GENERATED BY SYMPLRV3 — DO NOT EDIT
// Last settled response per api binding / SDK action id — the designer's
// "value from another API/SDK response" arg sources and api chains read it.
// Plain module state on purpose: reads happen at call time, not render time.
const store: Record<string, unknown> = {};

export function setLastResponse(id: string, body: unknown): void {
  store[id] = body;
}

export function lastResponse(id: string): unknown {
  return store[id];
}

/**
 * Drop every cached body. Called from clearSession().
 *
 * This store holds RAW API responses — balances, account numbers, whatever the
 * bindings returned — in plain module state that outlives a logout. Clearing
 * the token stops new requests being authorised; it does not empty this. The
 * same reasoning already applies to the form store and the query cache, and
 * this was the one that was missed.
 */
export function clearResponses(): void {
  for (const k of Object.keys(store)) delete store[k];
}
